INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Thug''s Ascension', 'A Thug''s Ascension is a low-poly action-adventure / FPS story set in the dying city of Maratha, circa 2023. Become Chief, a feared mercenary, and experience a dark, slow-paced, character-driven crime drama marrying cinematic dialogue-driven storytelling with intense shooting and driving gameplay.' FROM games WHERE igdb_id = 250817 ON CONFLICT (game_id, language_code) DO NOTHING;
