INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weedy''s World', 'Weedy''s World is a one or two-player game set in a U.P. Michigan dispensary called Glazed & Confused, players navigate a cannabis maze as Weedy or Ms. Weedy, collecting pot leaves and using power-ups while avoiding aliens. Inspired by Pac-Man, the game adds a unique twist with 420-themed humor.' FROM games WHERE igdb_id = 310778 ON CONFLICT (game_id, language_code) DO NOTHING;
