INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kilonova', 'Embark on a journey of revenge as Sol, a warrior of the celestial cosmos, as she fights to repel the corruption that has shackled the creatures of a fractured world. Wield her cosmic strength to shatter your foes and expunge the malevolent influence of the cosmos most ancient enemy; The Kilonova!' FROM games WHERE igdb_id = 310776 ON CONFLICT (game_id, language_code) DO NOTHING;
