INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000 Cuts: Jomaku', 'A samurai-inspired pixel-art side-scroller with simple-yet-satisfying combat, deeply consequential choices, and lore-rich storytelling. Hack and slash your way through the infamous Army of One-Thousand and reclaim your rightful place as daimyo, one cut at a time.' FROM games WHERE igdb_id = 288725 ON CONFLICT (game_id, language_code) DO NOTHING;
