INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RADS: The Radioactive Apocalypse Dating Simulator', 'A post-apocalyptic visual novel with choices and multiple endings. After being accidentally frozen in an Ice Cream Parlour freezer, our college-party-planning hero wakes decades later in a post-apocalyptic world of mutants, robots and monsters... determined to host a party and get a date!' FROM games WHERE igdb_id = 290822 ON CONFLICT (game_id, language_code) DO NOTHING;
