INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unables', 'Unables is really something else... A brand new comedy game with innovative, arcade gameplay, set in a cartoon world spoiled by extreme laziness. Our cast of classic heroes seem to have their "do nothing" skill maxed out. What to do when characters are so lazy, even you are unable to control them?' FROM games WHERE igdb_id = 212167 ON CONFLICT (game_id, language_code) DO NOTHING;
