INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Dead', 'Dive into a kilometer deep cave to find riches, lost technology and unnamed artifacts, but watch out, for "IT" slumbers in the forgotten depths. The game is a rogue-light slightly inspired by Spelunky where you have to reach the bottom to unlock upgrades, that is if the teeth in the dark will let you escape...' FROM games WHERE igdb_id = 323811 ON CONFLICT (game_id, language_code) DO NOTHING;
