INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destination Paradise: Collector''s Edition', '"Destination Paradise" is a hidden object game that takes players through 20 chapters, each set in different global locations. Every chapter contains three unique scenes, offering a range of challenges. The game includes various puzzle types such as jigsaw puzzles, tile-swapping, and tile-rotation. Players will also complete tasks like finding listed objects, unscrambling letters to form words, and solving riddles in an optional bonus mode.' FROM games WHERE igdb_id = 328716 ON CONFLICT (game_id, language_code) DO NOTHING;
