INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NTR''d By Clumsiness', 'A month after the death of his friend, Chris decides to invite his late friend''s son—Jeff—to stay at his house for two weeks while he''s in transition to go to college. On the eve of Jeff moving in, Chris decides to mention to his wife the danger that she''s about to face; the boy is unusually clumsy.' FROM games WHERE igdb_id = 236205 ON CONFLICT (game_id, language_code) DO NOTHING;
